["function", "core_image", "check_charge_atomic", "CREATE OR REPLACE FUNCTION core_image.check_charge_atomic()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE operation_id TEXT; operation RECORD; charge RECORD;
 image_price JSONB; ratio JSONB; ratio_name TEXT; part TEXT; raw_value TEXT;
 requested_n NUMERIC; maximum_n NUMERIC; max_budget NUMERIC;
 usd_num NUMERIC; usd_den NUMERIC; group_num NUMERIC; group_den NUMERIC;
 numerators NUMERIC[]; denominators NUMERIC[];
 gcd_a NUMERIC; gcd_b NUMERIC; remainder NUMERIC;
 base_numerator NUMERIC; base_denominator NUMERIC; base_credits NUMERIC;
 discounted_numerator NUMERIC; discounted_denominator NUMERIC;
 discounted_credits NUMERIC; trusted_reservation BIGINT; factor NUMERIC;
BEGIN
 IF TG_TABLE_SCHEMA='core_charging' THEN
  IF NEW.image_operation_id IS NULL THEN RETURN NULL; END IF;
  operation_id:=NEW.image_operation_id;
 ELSE operation_id:=NEW.id;
 END IF;
 SELECT o.* INTO operation FROM core_image.operations o WHERE o.id=operation_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'missing image operation source' USING ERRCODE='23514'; END IF;
 -- The old no-trust path is unchanged. New frozen evidence must also preserve
 -- the original Rust image quote's count, budget and base-overflow checks.
 -- Run before the no-charge return: previews must not persist an invalid base.
 IF operation.price ? 'user_trust' THEN
  image_price:=operation.price->'image';
  IF jsonb_typeof(image_price->'rule') IS DISTINCT FROM 'object'
     OR jsonb_typeof(image_price->'request') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid trusted image tariff shape' USING ERRCODE='23514';
  END IF;
  FOREACH ratio_name IN ARRAY ARRAY['usd_micros_per_image','group_multiplier'] LOOP
   ratio:=image_price#>ARRAY['rule',ratio_name];
   IF jsonb_typeof(ratio) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid trusted image ratio shape' USING ERRCODE='23514';
   END IF;
   IF NOT (ratio ?& ARRAY['numerator','denominator'])
      OR ratio-ARRAY['numerator','denominator']<>'{}'::jsonb THEN
    RAISE EXCEPTION 'invalid trusted image ratio fields' USING ERRCODE='23514';
   END IF;
   FOREACH part IN ARRAY ARRAY['numerator','denominator'] LOOP
    raw_value:=ratio->>part;
    IF jsonb_typeof(ratio->part) IS DISTINCT FROM 'number'
       OR raw_value !~ '^(0|[1-9][0-9]{0,19})$' THEN
     RAISE EXCEPTION 'invalid trusted image ratio integer' USING ERRCODE='23514';
    END IF;
    IF raw_value::numeric>18446744073709551615
       OR (part='denominator' AND raw_value::numeric=0) THEN
     RAISE EXCEPTION 'trusted image ratio outside u64 domain' USING ERRCODE='23514';
    END IF;
   END LOOP;
  END LOOP;
  IF jsonb_typeof(image_price#>'{request,n}') IS DISTINCT FROM 'number'
     OR image_price#>>'{request,n}' !~ '^[1-9][0-9]{0,2}$'
     OR jsonb_typeof(image_price#>'{rule,max_n}') IS DISTINCT FROM 'number'
     OR image_price#>>'{rule,max_n}' !~ '^[1-9][0-9]{0,2}$'
     OR jsonb_typeof(image_price#>'{rule,max_budget}') IS DISTINCT FROM 'number'
     OR image_price#>>'{rule,max_budget}' !~ '^(0|[1-9][0-9]{0,18})$' THEN
   RAISE EXCEPTION 'invalid trusted image count or budget integer' USING ERRCODE='23514';
  END IF;
  requested_n:=(image_price#>>'{request,n}')::numeric;
  maximum_n:=(image_price#>>'{rule,max_n}')::numeric;
  max_budget:=(image_price#>>'{rule,max_budget}')::numeric;
  IF requested_n>maximum_n OR maximum_n>128 OR max_budget>9223372036854775807 THEN
   RAISE EXCEPTION 'trusted image count or budget outside domain' USING ERRCODE='23514';
  END IF;
  usd_num:=(image_price#>>'{rule,usd_micros_per_image,numerator}')::numeric;
  usd_den:=(image_price#>>'{rule,usd_micros_per_image,denominator}')::numeric;
  group_num:=(image_price#>>'{rule,group_multiplier,numerator}')::numeric;
  group_den:=(image_price#>>'{rule,group_multiplier,denominator}')::numeric;
  -- Rust validates both the requested quote and the maximum configured count.
  -- Euclidean cancellation precedes each checked u128 base multiplication.
  FOR count_index IN 1..2 LOOP
   numerators:=ARRAY[usd_num,group_num,
       CASE WHEN count_index=1 THEN requested_n ELSE maximum_n END,500000::numeric];
   denominators:=ARRAY[usd_den,group_den,1000000::numeric];
   FOR numerator_index IN 1..4 LOOP
    FOR denominator_index IN 1..3 LOOP
     gcd_a:=numerators[numerator_index];
     gcd_b:=denominators[denominator_index];
     WHILE gcd_b<>0 LOOP
      remainder:=mod(gcd_a,gcd_b); gcd_a:=gcd_b; gcd_b:=remainder;
     END LOOP;
     numerators[numerator_index]:=div(numerators[numerator_index],gcd_a);
     denominators[denominator_index]:=div(denominators[denominator_index],gcd_a);
    END LOOP;
   END LOOP;
   base_numerator:=1; base_denominator:=1;
   FOREACH factor IN ARRAY numerators LOOP
    base_numerator:=base_numerator*factor;
    IF base_numerator>340282366920938463463374607431768211455 THEN
     RAISE EXCEPTION 'trusted image original numerator overflow' USING ERRCODE='23514';
    END IF;
   END LOOP;
   FOREACH factor IN ARRAY denominators LOOP
    base_denominator:=base_denominator*factor;
    IF base_denominator>340282366920938463463374607431768211455 THEN
     RAISE EXCEPTION 'trusted image original denominator overflow' USING ERRCODE='23514';
    END IF;
   END LOOP;
   base_credits:=div(base_numerator,base_denominator)
       + CASE WHEN mod(base_numerator,base_denominator)<>0 THEN 1 ELSE 0 END;
   IF base_credits>9223372036854775807 OR base_credits>max_budget
      OR (count_index=1 AND base_credits IS DISTINCT FROM
          (image_price->>'reservation_credits')::numeric) THEN
    RAISE EXCEPTION 'trusted image original reservation or budget mismatch' USING ERRCODE='23514';
   END IF;
  END LOOP;
  -- Multiply the trust factor into the complete exact amount. Never discount
  -- the already-rounded persisted base reservation, and never use numeric ceil
  -- on division whose scale may round away a nonzero remainder.
  discounted_numerator:=usd_num*group_num*requested_n*500000
      *(operation.price#>>'{user_trust,discount,numerator}')::numeric;
  discounted_denominator:=usd_den*group_den*1000000
      *(operation.price#>>'{user_trust,discount,denominator}')::numeric;
  discounted_credits:=div(discounted_numerator,discounted_denominator)
      + CASE WHEN mod(discounted_numerator,discounted_denominator)<>0 THEN 1 ELSE 0 END;
  IF discounted_credits>9223372036854775807 THEN
   RAISE EXCEPTION 'trusted image discounted reservation overflow' USING ERRCODE='23514';
  END IF;
  trusted_reservation:=discounted_credits::bigint;
 END IF;

 SELECT q.* INTO charge FROM core_charging.requests q WHERE q.image_operation_id=operation_id;
 IF NOT FOUND THEN
  IF operation.state NOT IN ('previewed','confirmed') OR operation.charge_id IS NOT NULL THEN
   RAISE EXCEPTION 'missing image charge' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
 END IF;
 IF charge.id<>operation.id OR charge.image_operation_id<>operation.id
    OR charge.actor_user_id<>operation.actor_user_id
    OR charge.owner_account_id<>operation.owner_account_id
    OR (operation.source_kind='drawing' AND (charge.key_id IS NOT NULL OR charge.payer_account_id<>operation.owner_account_id))
    OR (operation.source_kind='api_key' AND charge.key_id IS DISTINCT FROM operation.key_id)
    OR charge.oauth_source IS NOT NULL
    OR charge.assistant_grant_id IS NOT NULL OR charge.assistant_sponsor_account_id IS NOT NULL
    OR charge.fingerprint IS DISTINCT FROM operation.fingerprint OR charge.price IS DISTINCT FROM operation.price
    OR charge.reserved IS DISTINCT FROM (CASE WHEN operation.price ? 'user_trust' THEN trusted_reservation
       ELSE (operation.price#>>'{image,reservation_credits}')::bigint END)
    OR charge.input_tokens<>0 OR charge.cached_tokens<>0 OR charge.output_tokens<>0 THEN
  RAISE EXCEPTION 'image charge source mismatch' USING ERRCODE='23514';
 END IF;
 IF (operation.state='confirmed' AND (charge.state NOT IN ('reserved','released') OR operation.charge_id IS NOT NULL))
    OR (operation.state='dispatching' AND (charge.state NOT IN ('streaming','reconcile') OR operation.charge_id IS DISTINCT FROM charge.id))
    OR (operation.state='billing_pending' AND (charge.state NOT IN ('streaming','reconcile','settled') OR operation.charge_id IS DISTINCT FROM charge.id))
    OR operation.state='previewed'
    OR (operation.state='completed' AND charge.state<>'settled') THEN
  RAISE EXCEPTION 'image operation and charge states must commit together' USING ERRCODE='23514';
 END IF;
 IF charge.image_usage IS NOT NULL AND charge.image_usage IS DISTINCT FROM operation.image_usage THEN
  RAISE EXCEPTION 'image usage evidence mismatch' USING ERRCODE='23514';
 END IF;
 IF charge.state='settled' AND (operation.state NOT IN ('billing_pending','completed')
    OR operation.output IS NULL OR operation.image_usage IS DISTINCT FROM charge.image_usage
    OR charge.outcome IS DISTINCT FROM 'completed') THEN
  RAISE EXCEPTION 'image settlement requires durable original output receipt' USING ERRCODE='23514';
 END IF;
 IF operation.state='completed' AND (operation.charge_id IS DISTINCT FROM charge.id
    OR operation.settled_credits IS DISTINCT FROM charge.settled
    OR operation.image_usage IS DISTINCT FROM charge.image_usage
    OR operation.output IS NULL OR charge.outcome IS DISTINCT FROM 'completed') THEN
  RAISE EXCEPTION 'image output and completed settlement must commit together' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$
"]

["function", "core_image", "guard_operation", "CREATE OR REPLACE FUNCTION core_image.guard_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN
  RAISE EXCEPTION 'immutable image operation history' USING ERRCODE='55000';
 END IF;
 IF TG_OP='INSERT' THEN
  IF (NEW.source_kind='drawing' AND NEW.state<>'previewed')
     OR (NEW.source_kind='api_key' AND (NEW.state<>'confirmed' OR NEW.confirmed_at IS DISTINCT FROM NEW.created_at
         OR NEW.created_at>floor(extract(epoch FROM clock_timestamp()))::bigint
         OR NEW.expires_at<=floor(extract(epoch FROM clock_timestamp()))::bigint)) THEN
   RAISE EXCEPTION 'invalid initial image source state' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM core_identity.credentials c
      WHERE c.id=coalesce(NEW.session_id,NEW.key_id)
        AND c.kind=CASE WHEN NEW.source_kind='drawing' THEN 'session' ELSE 'api_key' END
        AND c.user_id=NEW.actor_user_id AND c.owner_account_id=NEW.owner_account_id
        AND c.user_version=NEW.auth_version) THEN
   RAISE EXCEPTION 'invalid original image credential binding' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF (OLD.state='completed' AND NEW IS DISTINCT FROM OLD)
    OR (to_jsonb(NEW)-ARRAY['state','confirmed_at','confirmation_digest','confirmation_sid','charge_id','output','output_digest','image_usage','settled_credits'])
       IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','confirmed_at','confirmation_digest','confirmation_sid','charge_id','output','output_digest','image_usage','settled_credits'])
    OR (OLD.confirmed_at IS NOT NULL AND NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at)
    OR (OLD.state<>'previewed' AND (NEW.confirmation_digest,NEW.confirmation_sid) IS DISTINCT FROM (OLD.confirmation_digest,OLD.confirmation_sid))
    OR (OLD.charge_id IS NOT NULL AND NEW.charge_id IS DISTINCT FROM OLD.charge_id)
    OR (OLD.output IS NOT NULL AND (NEW.output,NEW.output_digest,NEW.image_usage) IS DISTINCT FROM (OLD.output,OLD.output_digest,OLD.image_usage))
    OR (OLD.settled_credits IS NOT NULL AND NEW.settled_credits IS DISTINCT FROM OLD.settled_credits) THEN
  RAISE EXCEPTION 'immutable image operation facts' USING ERRCODE='23514';
 END IF;
 IF NEW.state<>OLD.state AND NOT (
    (OLD.state='previewed' AND NEW.state='confirmed')
    OR (OLD.state='confirmed' AND NEW.state='dispatching')
    OR (OLD.state='dispatching' AND NEW.state IN ('billing_pending','completed'))
    OR (OLD.state='billing_pending' AND NEW.state='completed')) THEN
  RAISE EXCEPTION 'invalid image operation transition' USING ERRCODE='23514';
 END IF;
 IF OLD.state='previewed' AND NEW.state='confirmed' AND
    (NEW.confirmed_at>floor(extract(epoch FROM clock_timestamp()))::bigint
     OR NEW.expires_at<=floor(extract(epoch FROM clock_timestamp()))::bigint) THEN
  RAISE EXCEPTION 'expired or future image confirmation' USING ERRCODE='23514';
 END IF;
 IF OLD.state='confirmed' AND NEW.state='dispatching' AND NEW.expires_at<=floor(extract(epoch FROM clock_timestamp()))::bigint THEN
  RAISE EXCEPTION 'expired image dispatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$
"]

["function", "core_image", "valid_output", "CREATE OR REPLACE FUNCTION core_image.valid_output(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE item JSONB;
BEGIN
 IF jsonb_typeof(value)<>'object'
    OR value-ARRAY['created','data']<>'{}'::jsonb
    OR jsonb_typeof(value->'data') IS DISTINCT FROM 'array'
    -- JSONB inserts structural spaces when printing an admitted provider JSON.
    -- Keep 4 KiB for that bounded (at most 128 items) representation overhead;
    -- the provider still enforces its 32 MiB payload + 64 KiB raw envelope.
    OR octet_length(value::text)>33624064 THEN RETURN FALSE; END IF;
 IF jsonb_array_length(value->'data') NOT BETWEEN 1 AND 128 THEN RETURN FALSE; END IF;
 IF value ? 'created' AND (jsonb_typeof(value->'created') IS DISTINCT FROM 'number'
    OR (value->>'created') !~ '^(0|[1-9][0-9]{0,19})$') THEN RETURN FALSE; END IF;
 FOR item IN SELECT e.value FROM jsonb_array_elements(value->'data') AS e(value) LOOP
  IF jsonb_typeof(item)<>'object'
     OR item-ARRAY['b64_json','url','revised_prompt']<>'{}'::jsonb
     OR (item ? 'b64_json')=(item ? 'url') THEN RETURN FALSE; END IF;
  IF item ? 'b64_json' AND (jsonb_typeof(item->'b64_json') IS DISTINCT FROM 'string'
     OR octet_length(item->>'b64_json') NOT BETWEEN 1 AND 33554432) THEN RETURN FALSE; END IF;
  IF item ? 'url' AND (jsonb_typeof(item->'url') IS DISTINCT FROM 'string'
     OR octet_length(item->>'url') NOT BETWEEN 1 AND 8192
     OR (item->>'url') !~ '^https://[^[:space:][:cntrl:]]+$') THEN RETURN FALSE; END IF;
  IF item ? 'revised_prompt' AND (jsonb_typeof(item->'revised_prompt') IS DISTINCT FROM 'string'
     OR octet_length(item->>'revised_prompt')>65536) THEN RETURN FALSE; END IF;
 END LOOP;
 -- This is a shape/size guard. Core independently parses URL credentials,
 -- validates base64 and removes provider credentials before saving this value.
 RETURN TRUE;
END $function$
"]

["function", "core_model", "checkpoint_output", "CREATE OR REPLACE FUNCTION core_model.checkpoint_output(p_request_id text, p_worker bytea, p_sequence bigint, p_packet_sha256 bytea, p_packet_bytes bigint, p_provider_usage jsonb, p_terminal_observed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE request core_charging.requests%ROWTYPE;
    previous core_model.output_checkpoints%ROWTYPE;
    duplicate core_model.output_checkpoints%ROWTYPE;
    at_time BIGINT;
BEGIN
    IF current_setting('transaction_isolation')<>'serializable' THEN
        RAISE EXCEPTION 'model evidence requires serializable' USING ERRCODE='25001';
    END IF;
    IF p_request_id IS NULL OR p_worker IS NULL OR p_sequence IS NULL
        OR p_packet_sha256 IS NULL OR p_packet_bytes IS NULL
        OR p_provider_usage IS NULL OR p_terminal_observed IS NULL
        OR octet_length(p_worker)<>32 OR octet_length(p_packet_sha256)<>32
        OR p_sequence NOT BETWEEN 1 AND 65536
        OR p_packet_bytes NOT BETWEEN 0 AND 134217728
        OR jsonb_typeof(p_provider_usage)<>'object'
        OR pg_column_size(p_provider_usage)>2048 THEN
        RAISE EXCEPTION 'invalid model evidence' USING ERRCODE='23514';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('core_charging:'||p_request_id,0));
    SELECT * INTO STRICT request FROM core_charging.requests
        WHERE id=p_request_id FOR UPDATE;
    IF request.worker_digest<>sha256(p_worker) THEN
        RAISE EXCEPTION 'wrong model worker' USING ERRCODE='42501';
    END IF;
    SELECT * INTO duplicate FROM core_model.output_checkpoints
        WHERE request_id=p_request_id AND sequence=p_sequence;
    IF FOUND THEN
        IF (duplicate.packet_sha256,duplicate.packet_bytes,duplicate.provider_usage,
            duplicate.terminal_observed) IS DISTINCT FROM
           (p_packet_sha256,p_packet_bytes,p_provider_usage,p_terminal_observed) THEN
            RAISE EXCEPTION 'conflicting model evidence' USING ERRCODE='23505';
        END IF;
        RETURN;
    END IF;
    at_time:=floor(extract(epoch FROM clock_timestamp()))::bigint;
    IF request.state<>'streaming' OR at_time>=request.lease_until
        OR at_time>=request.hard_deadline THEN
        RAISE EXCEPTION 'model worker is not live' USING ERRCODE='42501';
    END IF;
    SELECT * INTO previous FROM core_model.output_checkpoints
        WHERE request_id=p_request_id ORDER BY sequence DESC LIMIT 1;
    IF p_sequence<>coalesce(previous.sequence,0)+1
        OR (coalesce(previous.terminal_observed,FALSE) AND NOT p_terminal_observed)
        OR coalesce(previous.prepared_bytes,0)+p_packet_bytes>1073741824 THEN
        RAISE EXCEPTION 'invalid model evidence sequence' USING ERRCODE='23514';
    END IF;
    INSERT INTO core_model.output_checkpoints(request_id,sequence,packet_sha256,
        packet_bytes,prepared_bytes,provider_usage,terminal_observed)
        VALUES(p_request_id,p_sequence,p_packet_sha256,p_packet_bytes,
            coalesce(previous.prepared_bytes,0)+p_packet_bytes,p_provider_usage,
            p_terminal_observed);
END $function$
"]

["function", "core_oauth", "client_scope_set", "CREATE OR REPLACE FUNCTION core_oauth.client_scope_set(client_ text, values_ text[], initial_ boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE filtered_ TEXT[];
BEGIN
 IF cardinality(values_)<>(SELECT count(DISTINCT v) FROM unnest(values_) v) THEN RETURN FALSE; END IF;
 IF initial_ THEN
  IF client_='lmm' THEN RETURN cardinality(values_)=2 AND values_ @> ARRAY['catalog:read','balance:read']::text[]; END IF;
  RETURN client_='lmm-pi' AND cardinality(values_) BETWEEN 4 AND 7
   AND values_ @> ARRAY['catalog:read','balance:read','usage:read','models:invoke']::text[]
   AND values_ <@ ARRAY['catalog:read','balance:read','usage:read','models:invoke','mcp:bounties','mcp:drawing','remote:control']::text[];
 END IF;
 IF client_='lmm' THEN RETURN core_oauth.readonly_scope_set(values_); END IF;
 IF client_<>'lmm-pi' OR cardinality(values_) NOT BETWEEN 2 AND 68
    OR NOT (values_ && ARRAY['catalog:read','balance:read','usage:read','models:invoke']::text[]) THEN RETURN FALSE; END IF;
 filtered_:=array_remove(array_remove(values_,'usage:read'),'models:invoke');
 IF NOT (filtered_ && ARRAY['catalog:read','balance:read']::text[]) THEN filtered_:=filtered_||'catalog:read'::text; END IF;
 RETURN core_oauth.readonly_scope_set(filtered_);
END $function$
"]

["function", "core_oauth", "readonly_scope_set", "CREATE OR REPLACE FUNCTION core_oauth.readonly_scope_set(values_ text[])
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE value_ TEXT; encoded_ TEXT; raw_ BYTEA; group_ TEXT; reads_ INTEGER:=0; groups_ INTEGER:=0;
BEGIN
 IF cardinality(values_) NOT BETWEEN 2 AND 66 OR cardinality(values_)<>(SELECT count(DISTINCT v) FROM unnest(values_) v) THEN RETURN FALSE; END IF;
 FOREACH value_ IN ARRAY values_ LOOP
  IF value_ IN ('catalog:read','balance:read') THEN reads_:=reads_+1;
  ELSE
   IF value_ !~ '^group:[A-Za-z0-9_-]{2,86}$' THEN RETURN FALSE; END IF;
   encoded_:=substring(value_ FROM 7);
   raw_:=decode(translate(encoded_,'-_','+/')||repeat('=',(4-length(encoded_)%4)%4),'base64');
   IF octet_length(raw_) NOT BETWEEN 1 AND 64 OR rtrim(translate(replace(encode(raw_,'base64'),E'\n',''),'+/','-_'),'=')<>encoded_ THEN RETURN FALSE; END IF;
   group_:=convert_from(raw_,'UTF8');
   -- Match Rust char::is_control independent of the installation LC_CTYPE.
   -- PostgreSQL text/UTF8 conversion already rejects U+0000.
   IF group_ COLLATE "C" ~ U&'[\0001-\001F\007F-\009F]' THEN RETURN FALSE; END IF;
   groups_:=groups_+1;
  END IF;
 END LOOP;
 RETURN reads_ BETWEEN 1 AND 2 AND groups_ BETWEEN 1 AND 64;
EXCEPTION WHEN data_exception THEN RETURN FALSE;
END $function$
"]

["function", "core_wallet", "guard_transfer", "CREATE OR REPLACE FUNCTION core_wallet.guard_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE h core_billing.ledger_journals%ROWTYPE; f core_billing.ledger_journals%ROWTYPE;
        wallet_id bigint; held_id bigint; receiver_wallet bigint;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'wallet transfer immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'awaiting_confirmation' OR NEW.hold_journal IS NOT NULL OR NEW.final_journal IS NOT NULL OR NEW.recipient_user IS NOT NULL THEN
   RAISE EXCEPTION 'wallet transfer must start as draft' USING ERRCODE='23514';
  END IF;
 ELSE
  IF (NEW.id,NEW.owner_user,NEW.payer_account,NEW.request_key,NEW.amount,NEW.token_digest,NEW.created_at)
      IS DISTINCT FROM (OLD.id,OLD.owner_user,OLD.payer_account,OLD.request_key,OLD.amount,OLD.token_digest,OLD.created_at)
      OR (OLD.hold_journal IS NOT NULL AND NEW.hold_journal IS DISTINCT FROM OLD.hold_journal)
      OR (OLD.final_journal IS NOT NULL AND NEW.final_journal IS DISTINCT FROM OLD.final_journal)
      OR (OLD.confirmed_at IS NOT NULL AND NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at)
      OR (OLD.finished_at IS NOT NULL AND NEW.finished_at IS DISTINCT FROM OLD.finished_at)
      OR (OLD.recipient_user IS NOT NULL AND NEW.recipient_user IS DISTINCT FROM OLD.recipient_user) THEN
   RAISE EXCEPTION 'wallet original economics immutable' USING ERRCODE='23514';
  END IF;
  IF NOT (NEW.state=OLD.state OR (OLD.state='awaiting_confirmation' AND NEW.state='pending') OR (OLD.state='pending' AND NEW.state IN ('claimed','cancelled'))) THEN
   RAISE EXCEPTION 'wallet invalid transition' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM core_identity.users WHERE id=NEW.owner_user AND personal_account_id=NEW.payer_account) THEN
  RAISE EXCEPTION 'wallet payer is not original owner' USING ERRCODE='23514';
 END IF;
 IF NEW.hold_journal IS NOT NULL THEN
  SELECT * INTO h FROM core_billing.ledger_journals WHERE id=NEW.hold_journal;
  SELECT id INTO wallet_id FROM core_billing.ledger_accounts WHERE owner_account_id=NEW.payer_account AND bucket='wallet';
  SELECT id INTO held_id FROM core_billing.ledger_accounts WHERE owner_account_id=NEW.payer_account AND bucket='reserved';
  IF h.id IS NULL OR h.scope<>'core-wallet-transfer' OR h.operation_key<>('hold-'||NEW.id::text) OR h.kind<>'reserve'
      OR h.actor_user_id IS DISTINCT FROM NEW.owner_user OR h.amount_units<>NEW.amount
      OR h.payer_id IS DISTINCT FROM wallet_id OR h.payee_id IS DISTINCT FROM held_id THEN
   RAISE EXCEPTION 'wallet hold receipt mismatch' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.final_journal IS NOT NULL THEN
  SELECT * INTO f FROM core_billing.ledger_journals WHERE id=NEW.final_journal;
  IF f.id IS NULL OR f.scope<>'core-wallet-transfer' OR f.parent_journal_id IS DISTINCT FROM NEW.hold_journal OR f.amount_units<>NEW.amount THEN
   RAISE EXCEPTION 'wallet final receipt mismatch' USING ERRCODE='23514';
  END IF;
  IF NEW.state='claimed' THEN
   SELECT a.id INTO receiver_wallet FROM core_identity.users u JOIN core_billing.ledger_accounts a ON a.owner_account_id=u.personal_account_id AND a.bucket='wallet' WHERE u.id=NEW.recipient_user;
   IF NEW.recipient_user=NEW.owner_user OR f.kind<>'commerce_capture' OR f.operation_key<>('claim-'||NEW.id::text)
     OR f.actor_user_id IS DISTINCT FROM NEW.recipient_user OR f.payer_id IS DISTINCT FROM wallet_id OR f.payee_id IS DISTINCT FROM receiver_wallet THEN
    RAISE EXCEPTION 'wallet claim receipt mismatch' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.state='cancelled' THEN
   IF f.kind<>'release' OR f.operation_key<>('cancel-'||NEW.id::text) OR f.actor_user_id IS DISTINCT FROM NEW.owner_user
     OR f.payer_id IS DISTINCT FROM held_id OR f.payee_id IS DISTINCT FROM wallet_id THEN
    RAISE EXCEPTION 'wallet cancel receipt mismatch' USING ERRCODE='23514';
   END IF;
  ELSE RAISE EXCEPTION 'wallet nonterminal final receipt' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$
"]

["function", "public", "routing_guard_active", "CREATE OR REPLACE FUNCTION public.routing_guard_active()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE next_price bigint; old_price bigint; ready boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'routing active slot cannot be removed' USING ERRCODE = '23514';
    END IF;
    IF NEW.config_version IS NULL OR (OLD.config_version IS NOT NULL AND NEW.config_version <= OLD.config_version) THEN
        RAISE EXCEPTION 'routing version must increase' USING ERRCODE = '40001';
    END IF;
    SELECT c.price_version, c.sealed AND p.sealed INTO next_price, ready
        FROM routing_config_versions c JOIN routing_price_versions p ON p.version = c.price_version
        WHERE c.version = NEW.config_version;
    SELECT price_version INTO old_price FROM routing_config_versions WHERE version = OLD.config_version;
    IF ready IS DISTINCT FROM true OR next_price < old_price THEN
        RAISE EXCEPTION 'routing release is not ready' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
"]

["function", "public", "routing_guard_projection", "CREATE OR REPLACE FUNCTION public.routing_guard_projection()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v bigint;
    is_sealed boolean;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.version <> OLD.version THEN
        RAISE EXCEPTION 'routing version is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN v := OLD.version; ELSE v := NEW.version; END IF;
    IF TG_ARGV[0] = 'price' THEN
        SELECT sealed INTO is_sealed FROM routing_price_versions WHERE version = v FOR SHARE;
    ELSE
        SELECT sealed INTO is_sealed FROM routing_config_versions WHERE version = v FOR SHARE;
    END IF;
    IF is_sealed IS DISTINCT FROM false THEN
        RAISE EXCEPTION 'routing snapshot is sealed' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$
"]

["function", "public", "routing_guard_version", "CREATE OR REPLACE FUNCTION public.routing_guard_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'routing snapshot is immutable' USING ERRCODE = '23514';
    END IF;
    IF OLD.sealed OR NEW.version <> OLD.version OR NEW.document IS DISTINCT FROM OLD.document THEN
        RAISE EXCEPTION 'routing snapshot is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_TABLE_NAME = 'routing_config_versions'
        AND to_jsonb(NEW)->'price_version' IS DISTINCT FROM to_jsonb(OLD)->'price_version' THEN
        RAISE EXCEPTION 'routing price reference is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
"]

["function", "public", "routing_publish_config", "CREATE OR REPLACE FUNCTION public.routing_publish_config(p_document jsonb, p_price bigint, p_expected_config bigint, p_expected_price bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v bigint := (p_document->>'version')::bigint;
    old_config bigint;
    old_price bigint;
BEGIN
    SELECT config_version INTO old_config FROM routing_active_release WHERE singleton FOR UPDATE;
    SELECT price_version INTO old_price FROM routing_config_versions WHERE version = old_config;
    IF old_config IS DISTINCT FROM p_expected_config OR old_price IS DISTINCT FROM p_expected_price
        OR (old_config IS NOT NULL AND v <= old_config) THEN
        RAISE EXCEPTION 'routing publication conflict' USING ERRCODE = '40001';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM routing_price_versions WHERE version = p_price AND sealed)
        OR (old_price IS NOT NULL AND p_price < old_price) THEN
        RAISE EXCEPTION 'routing price version is unavailable' USING ERRCODE = '23514';
    END IF;
    INSERT INTO routing_config_versions(version, price_version, document) VALUES (v, p_price, p_document);
    INSERT INTO routing_groups
        SELECT v, g->>'name', (g->>'enabled')::boolean FROM jsonb_array_elements(p_document->'groups') g;
    INSERT INTO routing_upstreams
        SELECT v, (u->>'id')::bigint, u->>'endpoint', u->>'protocol',
            (u->'credential'->>'id')::bigint, (u->'credential'->>'revision')::bigint,
            (u->>'enabled')::boolean FROM jsonb_array_elements(p_document->'upstreams') u;
    INSERT INTO routing_routes
        SELECT v, (r->>'id')::bigint, r->>'group', r->>'model', (r->>'enabled')::boolean,
            ARRAY(SELECT jsonb_array_elements_text(r->'speeds')),
            (r->'failover'->>'max_attempts')::smallint,
            ARRAY(SELECT jsonb_array_elements_text(r->'failover'->'retry_on')),
            (r->'failover'->>'allow_replay_after_send')::boolean
        FROM jsonb_array_elements(p_document->'routes') r;
    INSERT INTO routing_targets
        SELECT v, (t->>'id')::bigint, (r->>'id')::bigint, (t->>'upstream_id')::bigint,
            t->>'upstream_model', (t->>'enabled')::boolean, (t->>'priority')::integer,
            (t->>'weight')::bigint, ARRAY(SELECT jsonb_array_elements_text(t->'speeds')),
            t->'payload', (t->>'timeout_ms')::integer
        FROM jsonb_array_elements(p_document->'routes') r,
            LATERAL jsonb_array_elements(r->'targets') t;
    INSERT INTO routing_aliases
        SELECT v, a->>'group', a->>'alias', a->>'model'
        FROM jsonb_array_elements(p_document->'aliases') a;
    UPDATE routing_config_versions SET sealed = true WHERE version = v;
    UPDATE routing_active_release SET config_version = v WHERE singleton;
END;
$function$
"]

["function", "public", "routing_stage_prices", "CREATE OR REPLACE FUNCTION public.routing_stage_prices(p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE v bigint := (p_document->>'version')::bigint; existing jsonb; inserted bigint;
BEGIN
    INSERT INTO routing_price_versions(version, document) VALUES (v, p_document)
        ON CONFLICT (version) DO NOTHING RETURNING version INTO inserted;
    IF inserted IS NULL THEN
        SELECT document INTO existing FROM routing_price_versions WHERE version = v AND sealed;
        IF existing IS DISTINCT FROM p_document THEN
            RAISE EXCEPTION 'price version already exists' USING ERRCODE = '23505';
        END IF;
        RETURN;
    END IF;
    INSERT INTO routing_price_rules
        SELECT v, (r->>'id')::bigint, r->>'model', r->>'group', r->>'speed',
            (r->'rates'->>'input')::bigint, (r->'rates'->>'output')::bigint,
            (r->'rates'->>'cache_read')::bigint, (r->'rates'->>'cache_write')::bigint,
            (r->'rates'->>'request')::bigint,
            (r->>'group_multiplier_ppm')::bigint, (r->>'speed_multiplier_ppm')::bigint
        FROM jsonb_array_elements(p_document->'rules') r;
    UPDATE routing_price_versions SET sealed = true WHERE version = v;
END;
$function$
"]
